	# svg_icon(:instagram, class: "no-margin-right"); atribut lain (role, tabindex, aria-*, data-*)
	# dipasang di <i>. Tanpa aria-label ikon dianggap dekoratif (aria-hidden).
	def svg_icon(name, **options)
		width, path = ICONS.fetch(name.to_s)
		svg = tag.svg(tag.path(d: path), xmlns: 'http://www.w3.org/2000/svg', viewBox: "0 0 #{width} #{ICON_HEIGHT}",
		              width: "#{(width / ICON_HEIGHT.to_f).round(4)}em", height: '1em', focusable: 'false', 'aria-hidden': 'true')
		options[:class] = ['svg-icon', options[:class]].compact.join(' ')
		options[:'aria-hidden'] = 'true' unless options.key?(:'aria-label') || options.key?('aria-label')
		content_tag(:i, svg, options)
	end
